export function parse(input) {
  const raw = String(input).trim();
  if (raw === "") return { empty: true, name: "" };
  const parts = raw.split("|");
  return { empty: false, name: parts[0], ageStr: parts[1] };
}

export function validate(p) {
  if (p.empty) return { ok: true, out: "EMPTY" };
  if (!p.name) return { ok: false, out: "INVALID:missing-name" };
  const age = Number(p.ageStr);
  if (Number.isNaN(age)) return { ok: false, out: "INVALID:bad-age" };
  if (age < 0) return { ok: false, out: "INVALID:negative-age" };
  if (age > 150) return { ok: false, out: "INVALID:age-too-large" };
  return { ok: true, name: p.name, age };
}

export function format(v) {
  if (v.out !== undefined) return v.out;
  const label = v.name.length > 10 ? v.name.slice(0, 10) + ".." : v.name;
  const bucket = v.age < 18 ? "minor" : v.age < 65 ? "adult" : "senior";
  return label + ":" + bucket;
}

export function process(input) {
  return format(validate(parse(input)));
}
